(()=>{if(window.__hsjDupsBatch20261023)return;window.__hsjDupsBatch20261023=true;
const esc2=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;'}[c]));
const key=x=>{const cpf=String(x.cpf||'').replace(/\D/g,'');return cpf.length===11?'cpf:'+cpf:'nome:'+String(x.patient_name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().trim()};
window.hsjShowDupBatch=function(){const counts=new Map();S.rows.filter(x=>x.active).forEach(x=>{const k=key(x);counts.set(k,(counts.get(k)||0)+1)});const dup=S.rows.filter(x=>x.active&&counts.get(key(x))>1);document.getElementById('modal').innerHTML='<div class="back"><div class="modal"><div class="mh"><b>Cadastros duplicados — seleção de dois</b><button class="btn" onclick="document.getElementById(\'modal\').innerHTML=\'\'">Fechar</button></div><div class="mb"><div class="notice">Esta ação DESATIVA os dois cadastros selecionados, não os apaga. Nenhum permanecerá ativo. Confira se não há atendimentos legítimos em andamento; o histórico será mantido.</div>'+dup.map(x=>'<label class="check"><input type="checkbox" class="hsjDupCheck" value="'+x.id+'"> '+esc2(x.patient_name)+' | CPF '+esc2(x.cpf||'—')+' | IDS '+esc2(x.ids||'—')+' | '+esc2(labels[x.stage]||x.stage)+' | '+esc2(x.procedure_name||'')+'</label>').join('')+'</div><div class="mf"><button class="btn red" onclick="hsjDeactivateTwo()">Desativar os dois cadastros selecionados</button></div></div></div>'};
window.hsjDeactivateTwo=async function(){const ids=[...document.querySelectorAll('.hsjDupCheck:checked')].map(x=>x.value);if(ids.length!==2)return alert('Selecione exatamente dois cadastros.');if(!confirm('ATENÇÃO: os DOIS cadastros deixarão de aparecer nas listas ativas. Verifique que nenhum dos dois deve continuar ativo. Confirmar?'))return;if(!confirm('Última confirmação: desativar os dois registros mantendo os históricos?'))return;try{await api('/rest/v1/rpc/hsj_desativar_duplicados_em_lote',{method:'POST',body:JSON.stringify({p_ids:ids})});document.getElementById('modal').innerHTML='';await load();renderCurrent();alert('Dois cadastros desativados. Históricos preservados.')}catch(e){alert('Operação cancelada: '+e.message)}};
const render=window.renderCurrent;window.renderCurrent=function(){const result=render.apply(this,arguments);const root=document.getElementById('content');if(root&&!root.querySelector('[data-dup-batch]')){const btn=document.createElement('button');btn.className='btn orange small';btn.dataset.dupBatch='1';btn.textContent='⚠ Revisar e desativar 2 duplicados';btn.onclick=window.hsjShowDupBatch;root.prepend(btn)}return result};
})();